const labels = { admitted: 'ADMITIDO', rejected: 'NO ADMITIDO', pending: 'EN REVISION' };
return items.map(item => ({
  json: {
    to: item.json.email || 'sin-correo@demo.local',
    subject: 'SION UNAC - Resultado de admision: ' + (labels[item.json.decision] || item.json.decision),
    name: item.json.name || 'Aspirante',
    decision: item.json.decision,
    program: item.json.program,
    period: item.json.period,
    body: 'Hola ' + (item.json.name || 'Aspirante') + ', tu resultado de admision para ' + item.json.program + ' (periodo ' + item.json.period + ') es: ' + (labels[item.json.decision] || item.json.decision) + '.',
    sentAt: new Date().toISOString()
  }
}));
